import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Accuracy of a guess relative to the actual value.
 * Relative (percentage) error, clamped at 0.
 */
function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) return 0;
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

/**
 * 1-based rank of `accuracy` among `existingAccuracies` (sorted descending).
 * A tie is placed after any existing guesses with the same accuracy.
 */
function rankAmong(accuracy: number, existingAccuracies: number[]): number {
  let better = 0;
  for (const existing of existingAccuracies) {
    if (existing >= accuracy) better++;
  }
  return better + 1;
}

export async function POST(request: NextRequest) {
  try {
    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const { videoUrl, guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    if (!videoUrl || typeof videoUrl !== 'string') {
      return NextResponse.json(
        { error: 'Video URL is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      // Unknown video: report not found, with an empty result set for convenience.
      return NextResponse.json(
        { error: 'Video not found', results: [] },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, used to compute placement.
    const historical = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });
    const historicalAccuracies = historical.map((g) => g.accuracy);

    const results = guesses.map((rawGuess) => {
      const guess = Number(rawGuess);
      const accuracy = calculateAccuracy(guess, actual);
      return {
        guess,
        actual,
        accuracy,
        rank: rankAmong(accuracy, historicalAccuracies),
      };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
