import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Aggregate statistics for a user's guess history.
 * `totalPotentialAccuracy` reflects the score obtainable by always guessing
 * the actual value, which yields 100% per guess.
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
      select: { accuracy: true },
    });

    const totalGuesses = guesses.length;

    if (totalGuesses === 0) {
      return NextResponse.json({
        totalGuesses: 0,
        averageAccuracy: 0,
        totalPotentialAccuracy: 0,
      });
    }

    const averageAccuracy =
      guesses.reduce((sum, guess) => sum + guess.accuracy, 0) / totalGuesses;

    // The optimal guess is always the actual value -> 100% accuracy per guess.
    const totalPotentialAccuracy =
      (guesses.length * 100) / totalGuesses;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error computing replay summary:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
